  g("hông phải").forEach(p=>dat(p, x0+W-t17,  x0+W,   y0, y0+ +p.h, 0, +p.w));
  g("nóc").forEach(p=>dat(p, x0+(W- +p.w)/2, x0+(W+ +p.w)/2, y0+Hh-t17, y0+Hh, 0, +p.h));
  g("đáy").forEach(p=>dat(p, x0+(W- +p.w)/2, x0+(W+ +p.w)/2, y0,        y0+t17, 0, +p.h));
