    const hc=(mn[0]&&+mn[0].h)||0;
    const wH=(ts[0]&&+ts[0].w)||(dh[0]&&+dh[0].w)||0;      /* bề ngang hộp  (iw−60) */
    const dH=(hop2[0]&&+hop2[0].w)||(dh[0]&&+dh[0].h)||0;  /* chiều sâu hộp (D−50)  */
