        let C=null;
        if((o.i+1)%nPB===o2.i) C=f.pts[(o.i+1)%nPB];    /* chung dinh cuoi cua `o` */
        else if((o2.i+1)%nPB===o.i) C=f.pts[o.i];       /* chung dinh dau cua `o` */
