      const t=tu[g.tu], vai=(/^T\d+\.([A-Z]+)/.exec(g.ma)||[])[1]||"";
      const cx=(g.bb[0]+g.bb[3])/2, tx=(t[0]+t[3])/2;
      if(vai==="T"||vai==="V"||vai==="X"||vai==="K") g.o[0]=(cx-tx)*0.45;
