    L(S,0,yt,W,yt,"khong"); L(S,x0,0,x0,yt,"khong"); L(S,x1,0,x1,yt,"khong"); const hc=hocTV(S,W,Hc,x0,x1,w); const yk1=hc.y0-cl(Hc*.055,150,160), yk0=yk1-cl(Hc*.055,150,160);
    L(S,x0,yk1,x1,yk1,"khong"); L(S,x0,yk0,x1,yk0,"khong"); H.suyDan(S);
