      const cy=Y(tu.h)-16-28-hSec;
      g.save(); g.strokeStyle="#111"; g.lineWidth=1; g.strokeRect(X(t),cy,wSec,hSec); g.restore();
      /* thùng kéo: hẹp hơn lòng hộc 2×12,5 mm, lùi 25 mm phía trước */
