  const dung=new Set(S? S.mat.map(f=>f.ma):[]); dung.add(giu);
  const xoa=Object.keys(_texTam).filter(k=>!dung.has(k))
    .sort((a,b)=>_texTam[a].luc-_texTam[b].luc);
