  /* BS82 §1 — cau su that, dat TRUOC cac cau khac vi no noi ve thu khach vua MAT. */
  const _gl=[]; if(_goUon) _gl.push(_goUon+" mặt uốn"); if(_goBo) _gl.push(_goBo+" góc bo");
  if(_gl.length) nhac("lam sóng là thanh định hình, không uốn và không bo góc được — đã gỡ "
    +_gl.join(" và ")+". Bấm hoàn tác nếu muốn giữ.");
  else if(bo.length) nhac("đã đổi kiểu mặt cho "+duoc.length+" mảng · bỏ qua "+bo.length
    +" phần của khối tủ (tấm 17 mm)");
