    if(B.ds&&B.khoa===khoa) return B.ds;
    const g=window.VACH_CNC&&window.VACH_CNC.goiTep();
    const ten=(g&&g.tep||[]).map(t=>t.ten).filter(t=>!/^tu-the-khac\//.test(t));
    const ten8=ten.filter(t=>/^tam-\d+/.test(t)), ten17=ten.filter(t=>/^tu-\d+/.test(t));
